  "lastModified" timestamptz,
  "lastPurchasePrice" double precision,
  "notes" text,
  "origin" text,
  "photoUrl" text,
  "ownerId" uuid,
  "shareCode" text unique default upper(substr(replace((gen_random_uuid())::text, '-'::text, ''::text), 1, 6))
);

